pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a helper that selfdestructs and sends all its balance to the caller
        address target = address(new Killer());
        // Fund the target so selfdestruct sends something
        vm.deal(target, 1 ether);
        // Now call forward with the target's address and empty data to trigger selfdestruct
        vm.deal(address(c), 1 ether); // give C some ether to potentially lose
        // Record balances before
        uint256 balanceBefore = address(c).balance;
        // Call forward - in reference reverts, in buggy succeeds and sends target's balance to C
        vm.prank(address(0xdead));
        bool ok;
        bytes memory emptyData;
        try c.forward(target, emptyData) {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference reverts => ok = false, balance unchanged. Buggy succeeds => ok = true, balance may increase.
        // Assert that the call reverted, which only the reference does.
        assertTrue(!ok, "forward should revert on failing call");
    }
}

contract Killer {
    fallback() external payable {
        selfdestruct(payable(msg.sender));
    }
}

