pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Use a non-existent address that will cause call to return false
        address nonexistent = address(0xdead);
        bytes memory emptyData = "";
        bool ok;
        try c.forward(nonexistent, emptyData) {
            ok = true;
        } catch {
            ok = false;
        }
        // The reference contract reverts (ok == false) because the call fails
        // The buggy contract does not revert (ok == true)
        assertTrue(!ok);
    }
}

