pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Call forward with a callee that will succeed (empty data to itself)
        bool ok;
        try c.forward(address(this), "") {
            ok = true;
        } catch {
            ok = false;
        }
        // The reference passes the require(_s) because the subcall succeeds, so ok = true.
        // The mutant always reverts inside the function (require(false)), so ok = false.
        assertTrue(ok == false, "Forward should have reverted in mutant but not in reference");
    }
}

