pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Call forward with a callee that always succeeds (empty data on address(this))
        bool ok;
        try c.forward(address(this), "") {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference does not revert (ok = true), mutant reverts (ok = false)
        assertTrue(ok, "Expected forward to succeed");
    }
}

